require 'rails_helper'

RSpec.describe "batches/index", type: :view do
  let(:game) { Game.create!(name: "Test Game") }
  
  before(:each) do
    assign(:batches, [
      Batch.create!(
        game_id: game.id,
        codename: "Codename",
        state: "pending"
      ),
      Batch.create!(
        game_id: game.id,
        codename: "Codename2",
        state: "in_progress"
      )
    ])
  end

  it "renders a list of batches" do
    controller.default_url_options = { locale: :ru }
    render
    
    # Check that both batches are rendered (codenames are generated by Faker)
    expect(rendered).to match(/Game:/)
    expect(rendered).to match(/Codename:/)
    expect(rendered).to match(/State:/)
    expect(rendered).to match(/Test Game/)
  end
end
